        check("genai batch creates an OpenAI batch on the uploaded file", seen()[-1]["path"] == "/v1/batches" and json.loads(seen()[-1]["body"]).get("endpoint") == "/v1/chat/completions" and seen()[-2]["path"] == "/v1/files", seen()[-2:])
