        check("vertex gemini image model returns inline image data", s == 200 and json.loads(b)["data"][0]["b64_json"] == "iVBORw0KGgo=" and seen()[-1]["path"].endswith("/models/gemini-2.5-flash-image:generateContent"), (s, b))
