        check("/bedrock/model-invocation-job creates the job as sent", s == 200 and seen()[-1]["path"] == "/model-invocation-job" and '"jobName":"native-job"' in seen()[-1]["body"], (s, b[:200]))
        s, _, b = call("GET", "/bedrock/model-invocation-jobs", None, BH)
