        _, d1, _ = ochat(OFF, "openai/gpt-4o-mini", "sk-bf-owner-budget", "owner cache check")
        _, d2, _ = ochat(OFF, "openai/gpt-4o-mini", "sk-bf-owner-a", "owner cache check")
